#FIRST WE MAKE A FUNCTION WHICH CREATES A DATAFRAME OF CORRELATIONS 
#BY OUTCOMES AND DATA COLLECTION GROUP
corrfunc <- function(Data)
{
  return(data.frame(cbind(n = rcorr(Data$UnBehTot, Data$LocusTot, type=c("pearson"))$n[1,2]),
                    Sex = round(rcorr(Data$UnBehTot, Data$T1_Sex, type=c("pearson"))$r[1,2], digits=3),
                    Machiavellianism = round(rcorr(Data$UnBehTot, Data$MachTot, type=c("pearson"))$r[1,2], digits = 3),
                    Locus = round(rcorr(Data$UnBehTot, Data$LocusTot, type=c("pearson"))$r[1,2], digits=3),
                    Peer = round(rcorr(Data$UnBehTot, Data$PeerTot, type=c("pearson"))$r[1,2], digits=3),
                    Manager = round(rcorr(Data$UnBehTot, Data$ManagerTot, type=c("pearson"))$r[1,2], digits=3),
                    Quality = round(rcorr(Data$UnBehTot, Data$QualityTot, type=c("pearson"))$r[1,2], digits=3)
  ))
}
